<?php
function attReady():bool {static $ready; if($ready!==null)return $ready;try{q('SELECT id FROM attendance_mutex WHERE id=1');return $ready=true;}catch(PDOException $e){return $ready=false;}}
function teaching(array $u):bool {return !empty($u['active'])&&$u['role']!=='student'&&attReady()&&(bool)one('SELECT user_id FROM tutor_permissions WHERE user_id=? AND enabled=1',[$u['id']]);}
function academic(array $u):bool{return roles($u,['admin','daa']);}
function attAccess(array $u):bool{return academic($u)||roles($u,['hod','pl'])||teaching($u);}
function attRequire(bool $ok,string $message='Access denied.'):void{if(!$ok)throw new RuntimeException($message);}
function attLock():void{q('UPDATE attendance_mutex SET revision=revision+1 WHERE id=1');}
function attAudit(?int $actor,string $event,?int $entity=null,array $details=[]):void{q('INSERT INTO attendance_audit(actor_id,event,entity_id,details,ip_address,created_at) VALUES(?,?,?,?,?,?)',[$actor,$event,$entity,json_encode($details,JSON_THROW_ON_ERROR),$_SERVER['REMOTE_ADDR']??'CLI',now()]);}
function attSettings():array{$out=[];foreach(all('SELECT * FROM attendance_settings')as $r)$out[$r['setting_key']]=(int)$r['setting_value'];return $out;}
function secureDevice():void{global $config;attRequire(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off','Device registration and QR attendance require HTTPS. Configure a trusted HTTPS URL first.');attRequire(str_starts_with($config['url'],'https://'),'Set the application URL to its HTTPS address in config/config.php.');}
function setDeviceCookie(string $name,string $token):void{setcookie($name,$token,['expires'=>time()+31536000,'path'=>'/','secure'=>true,'httponly'=>true,'samesite'=>'Lax']);}
function tutorDevice():array|false{$raw=$_COOKIE['__Host-cnr_tutor']??'';if(!preg_match('/^[a-f0-9]{64}$/',$raw))return false;$d=one('SELECT * FROM tutor_registered_devices WHERE token_hash=? AND active=1',[hash('sha256',$raw)]);if(!$d)return false;$u=one('SELECT * FROM users WHERE id=?',[$d['staff_id']]);return $u&&teaching($u)?array_merge($d,['staff'=>$u]):false;}
function boardDevice():array|false{$raw=$_COOKIE['__Host-cnr_board']??'';if(!preg_match('/^[a-f0-9]{64}$/',$raw))return false;return one('SELECT d.*,c.room_code,c.room_name FROM classroom_devices d JOIN classrooms c ON c.id=d.classroom_id WHERE d.token_hash=? AND d.active=1 AND c.active=1',[hash('sha256',$raw)]);}
function registerTutorDevice(array $u,string $name,string $password):string{attRequire(teaching($u));attRequire(password_verify($password,$u['password']),'Confirm your current password to register or replace your device.');attRequire(trim($name)!==''&&mb_strlen($name)<=160,'Enter a device name.');attLock();q('UPDATE tutor_registered_devices SET active=0,revoked_at=? WHERE staff_id=? AND active=1',[now(),$u['id']]);$raw=bin2hex(random_bytes(32));q('INSERT INTO tutor_registered_devices(staff_id,token_hash,device_name,user_agent,registered_at,created_ip) VALUES(?,?,?,?,?,?)',[$u['id'],hash('sha256',$raw),$name,substr($_SERVER['HTTP_USER_AGENT']??'',0,500),now(),$_SERVER['REMOTE_ADDR']??'CLI']);attAudit((int)$u['id'],'Device registered',(int)db()->lastInsertId());return $raw;}
function occurs(array $t,string $day):bool{return dateValid($day)&&$day>=$t['valid_from']&&$day<=$t['valid_until']&&(!$t['class_date']||$t['class_date']===$day)&&(int)date('N',strtotime($day))===(int)$t['weekday']&&(!empty($t['active'])||(!empty($t['disabled_at'])&&$day<substr($t['disabled_at'],0,10)));}
function scheduledRows():array{return all('SELECT t.*,u.name,u.email,u.active AS staff_active,COALESCE(c.room_code,\'Online\') AS room_code,c.room_name,c.active AS room_active FROM tutor_timetable t JOIN users u ON u.id=t.staff_id LEFT JOIN classrooms c ON c.id=t.classroom_id ORDER BY t.start_time,t.id');}
function attVisible(array $u,array $t):bool{return academic($u)||(roles($u,['hod','pl'])&&sessionMatches($t,'department',$u['department']))||(teaching($u)&&(int)$u['id']===(int)$t['staff_id']);}
function currentClass(int $room,?int $staff=null):array|false{$settings=attSettings();$matches=[];foreach(scheduledRows()as $t){if(!($t['attendance_required']??1)||($t['delivery_mode']??'In person')==='Online'||(int)$t['classroom_id']!==$room||!$t['staff_active']||!$t['room_active']||!occurs($t,date('Y-m-d')))continue;if($staff!==null&&!scheduledFor($t,$staff,date('Y-m-d')))continue;$start=strtotime(date('Y-m-d').' '.$t['start_time']);if(time()>=$start-$settings['early_minutes']*60&&time()<=$start+$settings['close_minutes']*60)$matches[]=$t;}attRequire(count($matches)<=1,'More than one class matches. Ask DAA to correct the timetable.');return $matches[0]??false;}
function issueQr(array $board):array{global $config;attLock();$ttl=attSettings()['qr_seconds'];$raw=bin2hex(random_bytes(32));q('INSERT INTO attendance_qr_sessions(classroom_id,classroom_device_id,token_hash,issued_at,expires_at) VALUES(?,?,?,?,?)',[$board['classroom_id'],$board['id'],hash('sha256',$raw),time(),time()+$ttl]);$id=(int)db()->lastInsertId();q('UPDATE classroom_devices SET last_seen_at=? WHERE id=?',[now(),$board['id']]);attAudit(null,'QR generated',$id,['room'=>$board['classroom_id']]);return ['url'=>rtrim($config['url'],'/').'/scan-attendance.php?t='.$raw,'expires'=>time()+$ttl];}
function scanContext(string $raw):array{attRequire((bool)preg_match('/^[a-f0-9]{64}$/',$raw),'Invalid QR.');$qr=one('SELECT q.* FROM attendance_qr_sessions q JOIN classroom_devices b ON b.id=q.classroom_device_id JOIN classrooms c ON c.id=q.classroom_id WHERE q.token_hash=? AND b.active=1 AND c.active=1',[hash('sha256',$raw)]);attRequire($qr&&(int)$qr['expires_at']>time()&&!$qr['used_at'],'QR expired or already used. Scan the current board QR.');$d=tutorDevice();attRequire((bool)$d,'This phone is not enrolled. Ask Admin for a one-time enrolment link, open it on this phone, then scan again.');$t=currentClass((int)$qr['classroom_id'],(int)$d['staff_id']);attRequire((bool)$t,'You have no class in this room within the attendance window.');return ['qr'=>$qr,'device'=>$d,'class'=>$t];}
function confirmAttendance(string $raw):int{attLock();$ctx=scanContext($raw);$t=$ctx['class'];$qr=$ctx['qr'];$d=$ctx['device'];$day=date('Y-m-d');attRequire(!one('SELECT id FROM tutor_attendance WHERE timetable_id=? AND attendance_date=?',[$t['id'],$day]),'Attendance already exists for this class.');$late=time()>strtotime($day.' '.$t['start_time'])+attSettings()['late_minutes']*60;$updated=q('UPDATE attendance_qr_sessions SET used_at=? WHERE id=? AND used_at IS NULL AND expires_at>?',[time(),$qr['id'],time()]);attRequire($updated->rowCount()===1,'QR already used or expired.');q('INSERT INTO tutor_attendance(timetable_id,staff_id,classroom_id,classroom_device_id,attendance_date,scheduled_start,scheduled_end,confirmed_at,attendance_status,registered_device_id,qr_session_id,ip_address,user_agent,remarks,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$t['id'],$d['staff_id'],$t['classroom_id'],$qr['classroom_device_id'],$day,$t['start_time'],$t['end_time'],now(),((int)$t['staff_id']!==(int)$d['staff_id']?'Substituted':($late?'Late':'Present')),$d['id'],$qr['id'],$_SERVER['REMOTE_ADDR']??'CLI',substr($_SERVER['HTTP_USER_AGENT']??'',0,500),'',now(),now()]);$id=(int)db()->lastInsertId();q('UPDATE tutor_registered_devices SET last_seen_at=?,last_ip=? WHERE id=?',[now(),$_SERVER['REMOTE_ADDR']??'CLI',$d['id']]);attAudit((int)$d['staff_id'],'Attendance confirmed',$id);return $id;}

function scheduledFor(array $t,int $staff,string $day):bool{
 if((int)$t['staff_id']===$staff)return true;
 return (bool)one("SELECT s.id FROM sessions s JOIN requests r ON r.id=s.request_id WHERE r.module='substitution' AND r.status='Approved' AND r.applicant_id=? AND s.faculty_id=? AND s.kind='Affected class' AND s.day=? AND s.module_code=? AND s.start_time=? AND s.end_time=?",[$t['staff_id'],$staff,$day,$t['subject_code'],$t['start_time'],$t['end_time']]);
}
